    if (i === 0) { bx(c, x - 2, y - 1, 4, 3, C); px(c, x + 2, y, A); px(c, x - 1, y - 1, H); } else if (i === 1) { sq(c, x, y, 4, H); px(c, x, y, A); } else { bx(c, x - 1, y - 3, 2, 5, C); px(c, x, y - 2, A); }
