  /* ---------- motions (mutate the scratch G; pp = time x speed) ---------- */
  PFA.motion('L02-rake', function (G, pp, k, ph) { G.fr = Math.min(3, Math.floor(((pp * 2.4 + ph) % 1) * 5)); G.t += G.fr * .6; });            /* stroke by stroke */
