    p(c, 3, 2, MOUSE); p(c, 4, 2, MOUSE); p(c, 2, 3, MOUSE); p(c, 3, 3, MOUSE); p(c, 1, 4, MOUSE); p(c, 2, 4, Hi);
    p(c, 3, 3, A); p(c, 5, 2, A); p(c, -2, 0, A); p(c, 1, 0, A);
