  PFA.motif('chill-mist', comp, { nm: 'cold breath', desc: 'pale wisps of cold cave air curling up off the edge, a frost speck at each tip', fam: 'puff', gap: 12, g: 'm03-mist', mo: 'm03-curl', x: 'haze', car: 'cloud' });
