    K.px(c, x - 2, y - 1, C); K.px(c, x - 2, y - 2, XC[13]); K.px(c, x + 1, y - 1, C); K.px(c, x + 1, y - 2, XC[13]); K.px(c, x + 4, y - 1, A);
