    if (fr === 3) { K.px(c, x + nx * 3, y + ny * 3, C); K.px(c, x + nx * 2 + tx, y + ny * 2 + ty, XC[13]); K.px(c, x + nx * 2 - tx, y + ny * 2 - ty, Hi); K.px(c, x + nx * 5, y + ny * 5, XC[7]); }
