    for (i = -4; i <= 3; i++) { X = x + nx * (i * .7) + tx * i * .5 + tx * (fr ? 1 : 0); Y = y + ny * (i * .7) + ty * i * .5 + ty * (fr ? 1 : 0); K.px(c, X, Y, (i & 1) ? Hi : C); K.px(c, X + tx, Y + ty, C); }
