    K.px(c, x - fl * 2, y + b, C); K.px(c, x - fl * 1, y + b, C); K.px(c, x, y + b, RED); K.px(c, x + fl, y + b, WHITE); K.px(c, x + fl * 2, y + b, WHITE);
    K.px(c, x - fl, y - 2 + b, EYE); K.px(c, x - fl * 2, y - 3 + b, C); K.px(c, x - fl * 2, y - 4 + b, A); K.px(c, x - fl * 3, y - 3 + b, C);
