    K.px(c, x + fl * 2, y - 2, A); K.px(c, x + fl * 2, y - 1, C); K.px(c, x + fl * 3, y - 3, C); K.px(c, x + fl * 3, y - 1, C); K.px(c, x + fl * 1, y - 2, Hi); K.px(c, x - fl * 1, y - 2, Hi);
