    for (i = 0; i < L; i++) K.px(c, x + fl * (3 + i), y + 1 + (i >> 1), XC[14]);
    if (fr >= 2) { K.px(c, x + fl * 2, y - 5, XC[11]); K.px(c, x - fl * 2, y - 6 - (fr & 1), XC[11]); K.px(c, x + fl * 1, y - 7, Hi); }
