    K.px(c, x - nx * 2 + tx * (o + 2), y - ny * 2 + ty * (o + 2), A); K.px(c, x + nx * (L - 2) + tx * (o + 1), y + ny * (L - 2) + ty * (o + 1), A);
    if (fr === 2) { X = x + nx * (L - 1); Y = y + ny * (L - 1); K.px(c, X + nx, Y + ny, K.WHITE); K.px(c, X + tx * 2, Y + ty * 2, Hi); K.px(c, X - tx * 2, Y - ty * 2, Hi); }
