  PFA.motion('m11-pose', function (G, pp, k, ph) { var w = (pp * 1.6 + ph) % 1; G.fr = w < .55 ? 0 : w < .8 ? 1 : 2; G.up += Math.round(Math.sin(pp * 7 + k) * .7); });
