    K.px(c, x + fl * (g === 1 ? 5 : g === 2 ? 2 : 3), y + 1, A); K.px(c, x - fl * (g === 1 ? 5 : g === 2 ? 2 : 3), y + 1, A);
    for (i = 1; i <= 5; i++) { X = x - fl * (4 + i); Y = y - 1 + Math.round(Math.sin(i * .8 + fr * 1.57) * .8) - (i > 3 ? 1 : 0); K.px(c, X, Y, C); K.px(c, X, Y + 1, A); if (i > 1 && i < 5) K.px(c, X, Y - 1, A); }
