    K.px(c, x - 1, y - 1, b ? A : XC[1]); K.px(c, x + 1, y - 1, b ? A : XC[1]); K.bx(c, x - 1, y + 1, 3, 1, Hi); K.px(c, x, y + 1, XC[1]);
