  M('fennec-sand-curtain', plain, { nm: 'sand curtains', desc: 'curtains of sand fanned up by two digging forepaws, the grains hanging in arcs', fam: 'puff', gap: 12, g: 'm13-sandfan', mo: 'm13-fling', x: 'dust', car: 'cloud' });
